package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ZoneinfoVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property zoneinfo of user profile ")
  void test_zoneinfo_v_o_builder() {
    Assertions.assertFalse(ZoneinfoVO.nullValue().getZoneinfo().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ZoneinfoVO.tryFrom(null).getZoneinfo().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ZoneinfoVO.from("one").getZoneinfo().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ZoneinfoVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ZoneinfoVO.from("one").toString());
  }
}
